contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 dummy) public payable {
        require(dummy >= 0);
        c.owned(); if (__ESBMC_reverted()) return;
        assert(c.owner() == address(this));
    }
